window.ScripturaLexicons.BDAG_PART_0021 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alethinos-bdag\" data-source=\"BDAG\" data-search=\"ἀληθινός alethinos verdadeiro confiável real genuíno autêntico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀληθινός</td><td>Adjetivo</td><td>verdadeiro; confiável; real</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aletho-bdag\" data-source=\"BDAG\" data-search=\"ἀλήθω aletho moer moinho martírio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλήθω</td><td>Verbo</td><td>moer</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alethos-bdag\" data-source=\"BDAG\" data-search=\"ἀληθῶς alethos verdadeiramente de fato realmente realmente verdadeiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀληθῶς</td><td>Advérbio</td><td>verdadeiramente; realmente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halieus-bdag\" data-source=\"BDAG\" data-search=\"ἁλιεύς halieus pescador pescadores homens pescar peixe BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλιεύς</td><td>Substantivo</td><td>pescador</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halieuo-bdag\" data-source=\"BDAG\" data-search=\"ἁλιεύω halieuo pescar pescaria João 21 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλιεύω</td><td>Verbo</td><td>pescar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halizo-bdag\" data-source=\"BDAG\" data-search=\"ἁλίζω halizo salgar sal tornar salgado Marcos 9 Mateus 5 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλίζω</td><td>Verbo</td><td>salgar; tornar salgado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alisgeo-bdag\" data-source=\"BDAG\" data-search=\"ἀλισγέω alisgeo contaminar profanar poluir Marcos 9 variante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλισγέω</td><td>Verbo</td><td>contaminar; profanar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alisgema-bdag\" data-source=\"BDAG\" data-search=\"ἀλίσγημα alisgema contaminação poluição ídolos Atos 15 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλίσγημα</td><td>Substantivo</td><td>contaminação; poluição</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alke-bdag\" data-source=\"BDAG\" data-search=\"Ἄλκη Alke Alce nome próprio Esmirna Inácio Policarpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἄλκη</td><td>Nome próprio</td><td>Alce</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-alethinos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀληθινός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alēthinós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Heráclito, Xenofonte, Platão e outros; inscrições, papiros, LXX, En; TestSol 13:8 C [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"-ῶς\" data-meanings=\"forma adverbial em -ῶς\">-ῶς</span>]; TestAbr A 4 p. 81, 4 [Stone p. 10]; TestJob; Test12Patr; JosAs 11 [cód. A p. 54, 6 Bat. e cód. Pal. 364]; ParJer 9:3; ApcSed 1:4; Fílon; Josefo; Ar. 15, 7; Justino.) “Verdadeiro”. <span class=\"sense-number\">1.</span> <strong>Relativo a estar de acordo com o que é verdadeiro: verdadeiro, digno de confiança</strong> (Xenofonte, <em>An.</em> 1, 9, 17; LXX). De Deus (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.34.6\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 34.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 14.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.8.86\" target=\"_blank\" rel=\"noopener noreferrer\">1Esd 8.86</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">3Mac 2.11</a>; Jos., <em>Ant.</em> 11, 55): com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιος\" data-meanings=\"santo\">ἅγιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6.10</a> (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθής\" data-meanings=\"verdadeiro\">ἀληθής</span>); com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀψευδής\" data-meanings=\"que não mente; veraz\">ἀψευδής</span>, MPol 14:2. Mais precisamente definido: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ κύριος ἀληθινὸς ἐν παντὶ ῥήματι\" data-meanings=\"o Senhor é verdadeiro em toda palavra\">ὁ κύριος ἀ. ἐν παντὶ ῥήματι</span>, Hm 3:1 (em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ψεῦδος\" data-meanings=\"falsidade; mentira\">ψεῦδος</span>). De Cristo, o juiz do mundo: com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιος\" data-meanings=\"santo\">ἅγιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3.7</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πιστός\" data-meanings=\"fiel\">πιστός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">3.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">19.11</a>. De Jó, 1 Cl 17:3 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 1.1</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθινὴ καρδία\" data-meanings=\"coração verdadeiro\">ἀ. καρδία</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.38.3\" target=\"_blank\" rel=\"noopener noreferrer\">Is 38.3</a>; TestDan 5:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.22</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ πέμψας με\" data-meanings=\"aquele que me enviou\">ὁ πέμψας με</span> = “aquele que me enviou pode garantir minhas credenciais”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.28</a> (diferentemente, veja 3 abaixo).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo a estar de acordo com os fatos, verdadeiro.</strong> Hm 3:5. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγος\" data-meanings=\"palavra; declaração\">λόγος</span> (Platão, <em>Rep.</em> 7, 522a e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1KI.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">3 Km 10.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Cr 9.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 6.13</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">10.1</a> Teod.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.37</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λόγοι\" data-meanings=\"palavras; declarações\">λόγοι</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2SA.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">2 Km 7.28</a>; En 99:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19.9</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πιστός\" data-meanings=\"fiel\">πιστός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">21.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">22.6</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαρτυρία\" data-meanings=\"testemunho\">μαρτυρία</span>, <strong>confiável</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.35</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κρίσις ἀληθινή\" data-meanings=\"julgamento verdadeiro\">κρίσις ἀ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 3.2</a> BA; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.59.4\" target=\"_blank\" rel=\"noopener noreferrer\">Is 59.4</a>; En 27:3), <strong>julgamento pelo qual a verdade é trazida à luz</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.16</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθής\" data-meanings=\"verdadeiro\">ἀληθής</span> v.l.); plural, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δίκαιος\" data-meanings=\"justo\">δίκαιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">19.2</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁδοί\" data-meanings=\"caminhos\">ὁδοί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">15.3</a>; compare Hv 3, 7, 1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Relativo a ser real, genuíno, autêntico: real.</strong> <strong>a.</strong> Em geral (Sócrates 6 p. 232, 27 Malherbe; Xenofonte, <em>Oec.</em> 10, 3; Platão, <em>Rep.</em> 6, 499c; Dio Crisóstomo 47 [64], 21 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἷμα ἀληθινόν\" data-meanings=\"sangue verdadeiro\">αἷμα ἀ.</span>; POxy 465, 108 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγαλμα κυάνου ἀληθινοῦ\" data-meanings=\"estátua de lápis-lazúli genuíno\">ἄγαλμα κυάνου ἀ.</span> = “estátua de lápis-lazúli genuíno”; PGM 8, 20; 41; 43 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἶδά σου καὶ τὰ βαρβαρικὰ ὀνόματα … τὸ δὲ ἀληθινὸν ὄνομά σου\" data-meanings=\"conheço também teus nomes bárbaros … mas teu nome verdadeiro\">οἶδά σου καὶ τ. βαρβαρικὰ ὀνόματα … τὸ δὲ ἀ. ὄνομά σου</span>; também IDefixWünsch p. 19s.; PGM 4, 278; 5, 115): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθινὴ πορφύρα\" data-meanings=\"púrpura genuína\">ἀ. πορφύρα</span>, GJs 10:1. Dos feitos de Jesus, Qua.</p>\n<p class=\"entry-text\"><strong>b.</strong> Frequentemente, de perspectivas cristãs: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθινὸν φῶς\" data-meanings=\"luz verdadeira\">ἀ. φῶς</span> (ParJer; Élio Aristides 23, 15 K. = 42 p. 772 D. [Asclep.]; Plotino, <em>Enn.</em> 6, 9, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2.8</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθινὴ τοῦ θεοῦ δύναμις\" data-meanings=\"verdadeiro poder de Deus\">ἀ. τ. θεοῦ δύναμις</span> (emenda para <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθειαν\" data-meanings=\"verdade\">ἀλήθειαν</span>), no final de Marcos no manuscrito Freer, 3s.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄμπελος\" data-meanings=\"videira\">ἄμπελος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 15.1</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄρτος\" data-meanings=\"pão\">ἄρτος</span>, <strong>o pão real da Eucaristia</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.32\" target=\"_blank\" rel=\"noopener noreferrer\">6.32</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζωή\" data-meanings=\"vida\">ζωή</span> (Fílon, <em>Leg. All.</em> 1, 32), IEph 7:2; compare 11:1; ITr 9:2; ISm 4:1. De Deus em contraste com outras divindades, que não são reais (PGM 7, 634s. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πέμψον μοι τὸν ἀληθινὸν Ἀσκληπιὸν δίχα τινὸς ἀντιθέου πλανοδαίμονος\" data-meanings=\"envia-me o verdadeiro Asclépio, sem qualquer espírito enganador adverso\">πέμψον μοι τὸν ἀ. Ἀσκληπιὸν δίχα τινὸς ἀντιθέου πλανοδαίμονος</span>; Fílon, <em>Leg. ad Gai.</em> 366; SibOr Fgm. 1, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.65.16\" target=\"_blank\" rel=\"noopener noreferrer\">Is 65.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">3Mac 6.18</a>; Just., <em>A I</em> 53, 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17.3</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μόνος\" data-meanings=\"único; somente\">μόνος</span> 1aδ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5.20</a> (veja A. Harnack, SBBerlAk 1915, 538s. = <em>Studien</em> I 1931, 110s.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1.9</a> (única referência em Paulo); 1 Cl 43:6. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθινὸς ὁ πέμψας με\" data-meanings=\"é real aquele que me enviou\">ἀ. ὁ πέμψας με</span>, <strong>alguém que é muito real me enviou</strong> (Goodsp.; mas veja 1 acima), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.28</a>. De seres humanos (Demóstenes 9, 12; 53, 8; 12 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθινὸς φίλος\" data-meanings=\"amigo verdadeiro\">ἀ. φίλος</span>; Políbio 1, 6, 5; 1, 80, 2; 3, 12, 6; Epicteto 4, 1, 154; 172; Ar. 15, 7 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ ἀδελφῷ ἀληθινῷ\" data-meanings=\"sobre um verdadeiro irmão\">ἐπὶ ἀδελφῷ ἀ.</span>; Just., <em>A II</em> 2, 14 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῷ ἀληθινῷ χριστιανῷ\" data-meanings=\"ao verdadeiro cristão\">τῷ ἀ. χριστιανῷ</span>; PHamb 37, 6 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀληθινὸς φιλόσοφος\" data-meanings=\"o verdadeiro filósofo\">ὁ ἀ. φιλόσοφος</span>; PGiss 40 II, 27 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθινοὶ Αἰγύπτιοι\" data-meanings=\"verdadeiros egípcios\">ἀ. Αἰγύπτιοι</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προσκυνηταί\" data-meanings=\"adoradores\">προσκυνηταί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.23</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προφῆται\" data-meanings=\"profetas\">προφῆται</span>, em contraste com falsos profetas, D 11:11; compare 13:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διδάσκαλος\" data-meanings=\"mestre\">διδάσκαλος</span>, em contraste com falsos mestres, D 13:2. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πάθος\" data-meanings=\"sofrimento\">πάθος</span>, <strong>o sofrimento real</strong> (em oposição ao docetismo), IEph inscr.; “verdadeiro” no sentido da realidade possuída apenas pelo arquétipo, não por suas cópias (Xenofonte, <em>Mem.</em> 3, 10, 7; Platão, <em>Leg.</em> 1 p. 643c, de brinquedos <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὄργανα σμικρά, τῶν ἀληθινῶν μιμήματα\" data-meanings=\"pequenos instrumentos, imitações dos verdadeiros\">ὄργανα σμικρά, τῶν ἀ. μιμήματα</span>. Do corpo real em contraste com sua representação artística: Alcidamante [séc. IV a.C.], <em>Soph.</em> 28 Blass; Teócrito, <em>Epigr.</em> n. 18 Gow = Anth. Pal. 9, 600; Ateneu 6, 253e): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σκηνὴ ἀληθινή\" data-meanings=\"tabernáculo verdadeiro\">σκηνὴ ἀ.</span>, <strong>o verdadeiro tabernáculo, o santuário celestial</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8.2</a>; o templo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀντίτυπα τῶν ἀληθινῶν\" data-meanings=\"cópias do verdadeiro santuário\">ἀντίτυπα τῶν ἀ.</span>, <strong>cópia do verdadeiro santuário</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">9.24</a>. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἀληθινόν\" data-meanings=\"o que é realmente bom; as verdadeiras riquezas\">τὸ ἀ.</span>, <strong>aquilo que é realmente bom</strong> (em contraste com o bem suposto, o <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄδικος μαμωνᾶς\" data-meanings=\"mamom injusto\">ἄδικος μαμωνᾶς</span>), <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πιστεύειν τὸ ἀληθινόν\" data-meanings=\"confiar as verdadeiras riquezas\">πιστεύειν τὸ ἀ.</span>, <strong>confiar as verdadeiras riquezas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.11</a> (compare Fílon, <em>Praem.</em> 104 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀληθινὸς πλοῦτος ἐν οὐρανῷ\" data-meanings=\"a verdadeira riqueza no céu\">ὁ ἀ. πλοῦτος ἐν οὐρανῷ</span>). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λανθάνω\" data-meanings=\"escapar à percepção\">λανθάνω</span>. M-M. TW. Spicq.</p>\n</section></article><article id=\"entry-aletho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλήθω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦alḗthō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Hipócrates; Teofrasto 4, 12, 13; Diod S 3, 13, 2; POxy 908, 26; 34 [séc. II d.C.]; PGM 4, 3097; LXX; Jos., <em>Ant.</em> 3, 270 e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.47.2\" target=\"_blank\" rel=\"noopener noreferrer\">Is 47.2</a> [1º aor. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤλεσα\" data-meanings=\"moí\">ἤλεσα</span>] usam <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλέω\" data-meanings=\"moer\">ἀλέω</span>, que segundo Phryn. p. 151 Lob. é ático por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθω\" data-meanings=\"moer\">ἀλήθω</span>; DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλέω\" data-meanings=\"moer\">ἀλέω</span>.) <strong>Moer.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τῷ μύλῳ\" data-meanings=\"no moinho; com o moinho manual\">ἐν τῷ μύλῳ</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 11.8</a>, imperf. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤληθον\" data-meanings=\"moíam\">ἤληθον</span>), <strong>com o moinho manual</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.41</a> (sobre o particípio, veja H. Riesenfeld, ConNeot 13, 1949, 12–16). Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθειν ἐπὶ τὸ αὐτό\" data-meanings=\"moer no mesmo lugar\">ἀ. ἐπὶ τὸ αὐτό</span>, <strong>moer no mesmo lugar</strong>, pois os moinhos costumam ser operados por duas mulheres, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.35</a>. Usado figuradamente do martírio por Inácio, que deseja ser moído como trigo de Deus pelos dentes das feras, IRo 4:1. — B. 362.</p>\n</section></article><article id=\"entry-alethos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀληθῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦alēthō̂s⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio (Ésquilo, Heródoto+), <strong>correspondente ao que realmente é assim: verdadeiramente, em verdade, realmente, de fato.</strong> <strong>a.</strong> Modificando um verbo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λέγειν\" data-meanings=\"dizer\">λέγειν</span>, <strong>dizer verdadeiramente</strong> (Dio Crisóstomo 33 [50], 7; PFay 123, 24; Just., <em>D.</em> 94, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.27</a>; IRo 8:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λαλεῖν\" data-meanings=\"falar\">λαλεῖν</span>, ibid.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γινώσκειν\" data-meanings=\"reconhecer; conhecer\">γινώσκειν</span>, <strong>reconhecer realmente</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">17.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰδέναι\" data-meanings=\"saber; perceber\">εἰδέναι</span>, <strong>perceber realmente, saber</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.11</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς τετελείωται\" data-meanings=\"é verdadeiramente aperfeiçoado\">ἀ. τετελείωται</span>, <strong>é verdadeiramente aperfeiçoado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2.5</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κτᾶσθαι\" data-meanings=\"adquirir\">κτᾶσθαι</span>, IEph 15:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πέμπειν\" data-meanings=\"enviar\">πέμπειν</span>, 17:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πράσσειν\" data-meanings=\"fazer; agir\">πράσσειν</span>, IMg 11; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐγείρεσθαι\" data-meanings=\"ressuscitar; levantar-se\">ἐγείρεσθαι</span>, ITr 9:2, compare v. 1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκλέγεσθαι\" data-meanings=\"ser escolhido\">ἐκλέγεσθαι</span>, Pol 1:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φρονεῖν\" data-meanings=\"pensar; ter disposição\">φρονεῖν</span>, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καλῶς\" data-meanings=\"bem\">καλῶς</span>, Hm 3:4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βλέπειν\" data-meanings=\"ver\">βλέπειν</span>, B 1:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατοικεῖν\" data-meanings=\"habitar\">κατοικεῖν</span>, 16:8; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζῆν\" data-meanings=\"viver\">ζῆν</span> (Cáriton 8, 6, 8), Dg 10:7. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καθὼς ἀληθῶς ἐστιν\" data-meanings=\"como realmente é\">καθὼς ἀ. ἐστιν</span> (de outro modo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὡς ἀληθῶς\" data-meanings=\"como realmente\">ὡς ἀ.</span>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">4Mac 6.5</a>), <strong>como realmente é</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2.13</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς καθηλωμένος\" data-meanings=\"pregado de fato\">ἀ. καθηλωμένος</span>, <strong>pregado de fato</strong>, ISm 1:2. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς θεοῦ υἱὸς εἶ\" data-meanings=\"verdadeiramente és Filho de Deus\">ἀ. θεοῦ υἱὸς εἶ</span>, <strong>verdadeiramente és Filho de Deus</strong> (compare Ésquilo, <em>Suppl.</em> 585), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.33</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.54\" target=\"_blank\" rel=\"noopener noreferrer\">27.54</a>. — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.73\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.73</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11.32</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.70\" target=\"_blank\" rel=\"noopener noreferrer\">14.70</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">15.39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.49</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">4.42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">6.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">7.40</a>; GPt 11:45; B 7:9; Dg 7:2; ISm 1:1; 2:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ ἄρα ἀληθῶς ἀπέθανεν\" data-meanings=\"se de fato morreu\">εἰ ἄρα ἀληθῶς ἀπέθανεν</span>, AcPt Ox 849, 3. Como fórmula de afirmação com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λέγω\" data-meanings=\"dizer\">λέγω</span> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμήν\" data-meanings=\"amém; verdadeiramente\">ἀμήν</span> 2), <strong>verdadeiramente, eu vos digo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">21.3</a>.</p>\n<p class=\"entry-text\"><strong>b.</strong> Em relação atributiva com substantivos (Platão, <em>Phd.</em> 129e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκεῖνός ἐστιν ὁ ἀληθῶς οὐρανός\" data-meanings=\"aquele é o céu verdadeiro\">ἐκεῖνός ἐστιν ὁ ἀληθῶς οὐρανός</span>; Plutarco, <em>Mor.</em> 352c; SIG 834, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/RUT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rt 3.12</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς ἀγχιστεὺς ἐγώ εἰμι\" data-meanings=\"realmente sou resgatador\">ἀληθῶς ἀγχιστεὺς ἐγώ εἰμι</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">4Mac 11.23</a>; Jos., <em>Ant.</em> 9, 256 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀληθῶς θεός\" data-meanings=\"o Deus verdadeiro\">ὁ ἀ. θεός</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἴδε ἀληθῶς Ἰσραηλίτης\" data-meanings=\"eis um verdadeiro israelita\">ἴδε ἀ. Ἰσραηλίτης</span>, <strong>eis um verdadeiro israelita</strong> (literalmente, “realmente um israelita”), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.47\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.47</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς μαθηταί μού ἐστε\" data-meanings=\"sois verdadeiramente meus discípulos\">ἀ. μαθηταί μού ἐστε</span>, <strong>sois verdadeiramente meus discípulos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">8.31</a>; compare IRo 4:2, onde se deve ler <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαθητὴς ἀληθῶς Ἰησοῦ Χριστοῦ\" data-meanings=\"verdadeiramente discípulo de Jesus Cristo\">μαθητὴς ἀληθῶς Ἰησοῦ Χριστοῦ</span> (assim Bihlmeyer; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθής\" data-meanings=\"verdadeiro\">ἀληθής</span> 3). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι ἀληθῶς νεκρός ἐστιν\" data-meanings=\"que está realmente morto\">ὅτι ἀ. νεκρός ἐστιν</span>, <strong>que está realmente morto</strong>, AcPt Ox 849, 4s. — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς οἰκοδομητὸς ναὸς διὰ χειρός\" data-meanings=\"um templo realmente construído por mãos\">ἀ. οἰκοδομητὸς ναὸς διὰ χειρός</span>, <strong>um templo realmente construído por mãos</strong>, B 16:7. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καθὼς ἀληθῶς ἐστιν\" data-meanings=\"como realmente é\">καθὼς ἀ. ἐστιν</span> (em lugar do qual também se encontra <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὡς ἀληθῶς\" data-meanings=\"como realmente\">ὡς ἀ.</span>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">4Mac 6.5</a>), <strong>como realmente é</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2.13</a>. — B 16, 7. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λανθάνω\" data-meanings=\"escapar à percepção\">λανθάνω</span>. Spicq.</p>\n</section></article><article id=\"entry-halieus-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁλιεύς</h1><div class=\"entry-meta\"><span class=\"greek\">έως, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦halieús⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Compare a forma locativa desusada <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλί\" data-meanings=\"forma locativa de ἅλς\">ἁλί</span> [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλς\" data-meanings=\"sal; mar\">ἅλς</span>], Schwyzer I 476 e compare 549; sobre a forma <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλεεῖς\" data-meanings=\"pescadores; forma variante\">ἁλεεῖς</span>, encontrada também em Arriano, <em>Anab.</em> 6, 23, 3 [com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλεέας\" data-meanings=\"pescadores; forma variante\">ἁλεέας</span> duas vezes como v.l.]; PFlor 127, 15 [256 d.C.]; BGU 1035, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.19.8\" target=\"_blank\" rel=\"noopener noreferrer\">Is 19.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.47.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 47.10</a>, e como v.l. em todas as passagens do NT; veja B-D-F §29, 5; W.-S. §5, 20a; Mlt-H. 76; 142; DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλς\" data-meanings=\"sal; mar\">ἅλς</span>.) <strong>Aquele cuja ocupação é capturar peixes, pescador</strong> (Homero+), literalmente: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.2</a>. Figuradamente, dos discípulos: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ποιήσω ὑμᾶς ἁλιεῖς ἀνθρώπων\" data-meanings=\"farei de vós pescadores de pessoas\">ποιήσω ὑμᾶς ἁ. ἀνθρώπων</span>, <strong>farei de vós pescadores de pessoas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.17</a> (C. Smith, HTR 52, 1959, 187–203), ligando alegoricamente suas vocações presente e futura (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.10</a> tem, em lugar disso, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνθρώπους ἔσῃ ζωγρῶν\" data-meanings=\"estarás capturando pessoas vivas\">ἀνθρώπους ἔσῃ ζωγρῶν</span>; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζωγρέω\" data-meanings=\"capturar vivo\">ζωγρέω</span>). A figura e a expressão encontram-se também em autores antigos (RhM n.s. 35, 1880, 413 n. 12. — Veja também Diógenes Laércio 4, 16, 17, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θηράω\" data-meanings=\"caçar; perseguir\">θηράω</span> = <strong>caçar</strong>, no sentido de “capturar alguém para o próprio ponto de vista”. Em 8, 36, Diógenes Laércio faz Timão [Fgm. 58 Diels] dizer de Pitágoras que ele saiu <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θήρῃ ἐπ’ ἀνθρώπων\" data-meanings=\"à caça de pessoas\">θήρῃ ἐπ’ ἀνθρώπων</span> = <strong>à caça de pessoas</strong>). — W. Wuellner, <em>The Meaning of ‘Fishers of Men’</em>, 1967. Veja também a literatura s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφιβάλλω\" data-meanings=\"lançar ao redor; lançar rede\">ἀμφιβάλλω</span>. — B. 184. M-M.</p>\n</section></article><article id=\"entry-halieuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁλιεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦halieúō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Como ativo, IG XII, 5, 126 [sécs. II/I a.C.]; Plutarco, <em>Ant.</em> 929 [29, 5] e outros; PFlor 275, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 16.16</a>; TestZeb 6:3, 7, 8. Como médio, Fílon, <em>Agr.</em> 24, <em>Plant.</em> 102.) <strong>Pescar</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπάγω ἁλιεύειν\" data-meanings=\"vou pescar\">ὑπάγω ἁλιεύειν</span>, <strong>vou pescar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21.3</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλς\" data-meanings=\"sal; mar\">ἅλς</span>. M-M.</p>\n</section></article><article id=\"entry-halizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁλίζω</h1><div class=\"entry-meta\"><span class=\"greek\">pass.: fut. ἁλισθήσομαι; 1 aor. ἡλίσθην; perf. ptc. ἡλισμένον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦halízō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Passivo: futuro <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλισθήσομαι\" data-meanings=\"serei salgado\">ἁλισθήσομαι</span>; 1º aoristo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡλίσθην\" data-meanings=\"fui salgado\">ἡλίσθην</span>; particípio perfeito <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡλισμένον\" data-meanings=\"salgado\">ἡλισμένον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 6.5</a> S (Aristóteles e outros; LXX; TestLevi 9:14; DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλς\" data-meanings=\"sal; mar\">ἅλς</span>). <strong>Salgar</strong>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τίνι ἁλισθήσεται;\" data-meanings=\"com que será tornado salgado novamente?\">ἐν τίνι ἁλισθήσεται;</span>, <strong>com que ele (o sal) será tornado salgado novamente?</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.13</a> (mas veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν\" data-meanings=\"em; por; com\">ἐν</span> 3).</p>\n<p class=\"entry-text\">Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.49</a>, a tradição manuscrita é incerta e o sentido obscuro; há três leituras: <span class=\"sense-number\">1.</span> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶς γὰρ πυρὶ ἁλισθήσεται\" data-meanings=\"pois todo [um] será salgado com fogo\">πᾶς γὰρ πυρὶ ἁλισθήσεται</span>. <span class=\"sense-number\">2.</span> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶσα γὰρ θυσία ἁλὶ ἁλισθήσεται\" data-meanings=\"pois todo sacrifício será salgado com sal\">πᾶσα γὰρ θυσία ἁλὶ ἁλισθ.</span> (D). <span class=\"sense-number\">3.</span> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶς γὰρ πυρὶ ἁλισθήσεται καὶ πᾶσα θυσία ἁλὶ ἁλισθήσεται\" data-meanings=\"pois todo [um] será salgado com fogo, e todo sacrifício será salgado com sal\">πᾶς γὰρ πυρὶ ἁλισθ. καὶ πᾶσα θυσία (ἁλὶ) ἁλισθ.</span>. Destas, 2 = 3b é uma exigência veterotestamentária para o sacrifício (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 2.13</a>); em 1 = 3a, o fogo serve como símbolo do sofrimento e do sacrifício pelos quais o discípulo é provado (diferentemente, W. Fields, <em>Grace Theological Journal</em> 6, 1985, 299–304). Veja a literatura em <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλας\" data-meanings=\"sal\">ἅλας</span> b e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πῦρ\" data-meanings=\"fogo\">πῦρ</span> c. De obscuridade apocalíptica semelhante é o dito de Heráclito, Fgm. 66: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πάντα τὸ πῦρ ἐπελθὸν κρινεῖ καὶ καταλήψεται\" data-meanings=\"o fogo, ao chegar, julgará e alcançará todas as coisas\">πάντα τὸ πῦρ ἐπελθὸν κρινεῖ καὶ καταλήψεται</span>.</p>\n<p class=\"entry-text\">Também figuradamente: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλίζεσθαι ἐν αὐτῷ\" data-meanings=\"ser salgado nele\">ἁλίζεσθαι ἐν αὐτῷ</span> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Χριστός\" data-meanings=\"Cristo\">Χριστῷ</span>), <strong>ser salgado por ele</strong>, isto é, apropriar-se de seu poder para impedir a corrupção, IMg 10:2.</p>\n</section></article><article id=\"entry-alisgeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλισγέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦alisgéō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Etimologia desconhecida; veja DELG; LXX.) <strong>Contaminar, poluir, profanar</strong>. Futuro passivo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλισγηθήσεται\" data-meanings=\"será contaminado\">ἀλισγηθήσεται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.49</a> v.l.; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλίζω\" data-meanings=\"salgar\">ἁλίζω</span>.</p>\n</section></article><article id=\"entry-alisgema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλίσγημα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alísgēma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Compare <em>Anecd. Gr.</em> p. 377, 1; Hesíquio; Suda; de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλισγέω\" data-meanings=\"tornar ritualmente impuro; contaminar\">ἀλισγέω</span>, “tornar ritualmente impuro”, LXX.) <strong>Contaminação, poluição</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπέχεσθαι τῶν ἀλισγημάτων τῶν εἰδώλων\" data-meanings=\"abster-se das contaminações dos ídolos\">ἀπέχεσθαι τῶν ἀ. τῶν εἰδώλων</span>, <strong>abster-se da contaminação</strong> (o plural denota atos distintos) <strong>por imagens</strong> (de divindades), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.20</a> (compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπέχεσθαι ἐκ τῶν ἀλισγημάτων τῶν ἐθνῶν τῆς Βαβυλῶνος\" data-meanings=\"abster-se das contaminações dos gentios de Babilônia\">ἀπέχεσθαι ἐκ τῶν ἀλισγημάτων τῶν ἐθνῶν τῆς Βαβυλῶνος</span>, ParJer 7:37 [= 7:32 H.]).</p>\n</section></article><article id=\"entry-alke-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἄλκη</h1><div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Álkē⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Alce</strong> (Iseu 6, 19; 20; 55; Diod S 5, 49, 3; CIG 3268 [Esmirna]; 7064; o latim <em>Alce</em> é mais frequente [CIL III 2477; VI 20852; IX 3201 e outros]), uma mulher de Esmirna, ISm 13:2; IPol 8:3; MPol 17:2.</p>\n</section></article>"};
